INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$g = \frac{V}{r\ln(R/r)}$', 'Electric Stress in a Single-Core Cable', '$g(x) = \frac{V}{x\ln(R/r)},\qquad g_{\max} = \frac{V}{r\ln(R/r)}\ (\text{at the conductor})$', '$\text{kV/cm}$', 'The electric field in a cable''s insulation, largest at the conductor surface.', '[{"symbol":"$V$","meaning":"conductor-to-sheath voltage","unit":"$\\text{kV}$"},{"symbol":"$r, R$","meaning":"conductor and insulation outer radii","unit":"$\\text{cm}$"},{"symbol":"$x$","meaning":"radius where the stress is wanted","unit":"$\\text{cm}$"}]'::jsonb, 'For a given R the maximum stress is least when r = R/e.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Apparatus & Devices' AND t."subject" = 'EE' AND s."normKey" = 'wires and cables' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Apparatus & Devices' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$t = H\left(\frac{C}{IH}\right)^k$', 'Peukert''s Law', '$t = H\left(\frac{C}{IH}\right)^k\quad (k \approx 1.1\text{–}1.3 \text{ lead-acid})$', '$\text{h}$', 'A battery delivers less capacity the faster it is discharged.', '[{"symbol":"$C$","meaning":"rated capacity at the H-hour rate","unit":"$\\text{Ah}$"},{"symbol":"$H$","meaning":"rated discharge time, e.g. 20 h","unit":"$\\text{h}$"},{"symbol":"$I$","meaning":"actual discharge current","unit":"$\\text{A}$"},{"symbol":"$k$","meaning":"Peukert exponent","unit":null}]'::jsonb, 'At k = 1 (ideal) t = C/I; lithium cells are close to that.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Apparatus & Devices' AND t."subject" = 'EE' AND s."normKey" = 'batteries and ups' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Apparatus & Devices' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$t = \frac{C\,V\,\eta\,\text{DoD}}{P}$', 'UPS Runtime', '$S_{UPS} \ge \frac{P_{load}}{\text{pf}},\qquad t = \frac{C\,V_{bank}\,\eta\,\text{DoD}}{P_{load}}$', '$\text{h}$', 'How long a UPS carries its load on battery, and the kVA it must be rated for.', '[{"symbol":"$C$","meaning":"battery capacity","unit":"$\\text{Ah}$"},{"symbol":"$V_{bank}$","meaning":"battery bank voltage","unit":"$\\text{V}$"},{"symbol":"$\\eta$","meaning":"inverter efficiency","unit":null},{"symbol":"$P_{load}$","meaning":"load power","unit":"$\\text{W}$"}]'::jsonb, 'Correct C for the discharge rate (Peukert) when the runtime is short.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Apparatus & Devices' AND t."subject" = 'EE' AND s."normKey" = 'batteries and ups' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Apparatus & Devices' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$\eta_{lum} = \frac{\Phi_{out}}{\Phi_{lamps}}$', 'Luminaire Efficiency', '$\eta_{luminaire} = \frac{\Phi_{out}}{\Phi_{lamps}}\ (\text{light output ratio}),\qquad \text{efficacy} = \frac{\Phi_{out}}{P_{in}}$', NULL, 'How much of the lamps'' light the fitting actually releases.', '[{"symbol":"$\\Phi_{out}$","meaning":"lumens leaving the luminaire","unit":"$\\text{lm}$"},{"symbol":"$\\Phi_{lamps}$","meaning":"bare-lamp lumens","unit":"$\\text{lm}$"},{"symbol":"$P_{in}$","meaning":"input watts including driver","unit":"$\\text{W}$"}]'::jsonb, 'LED luminaires are rated on luminaire lumens directly; compare luminaire efficacy (lm/W).', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Apparatus & Devices' AND t."subject" = 'EE' AND s."normKey" = 'lamps and luminaires' AND s."active"), NULL, true, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Apparatus & Devices' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
INSERT INTO "ReferenceCard" ("id", "kind", "symbol", "name", "formulaLatex", "valueUnit", "description", "variables", "purposeExamTip", "subject", "topicId", "subtopicId", "subtopicTag", "dimensionless", "status", "createdAt", "updatedAt")
SELECT gen_random_uuid()::text, 'formula', '$L_{70} = \frac{\ln(1/0.7)}{\alpha}$', 'LED L70 Life', '$\Phi(t) = \Phi_0e^{-\alpha t},\qquad L_{70} = \frac{\ln(1/0.7)}{\alpha}$', '$\text{h}$', 'LEDs rarely fail outright; their life is the hours until output falls to 70%.', '[{"symbol":"$\\alpha$","meaning":"lumen decay rate fitted from test data","unit":"$\\text{1/h}$"},{"symbol":"$\\Phi_0$","meaning":"initial lumens","unit":"$\\text{lm}$"}]'::jsonb, 'Heat shortens L70 sharply: luminaire thermal design matters as much as the chip.', 'EE', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Electrical Apparatus & Devices' AND t."subject" = 'EE' AND s."normKey" = 'lamps and luminaires' AND s."active"), NULL, false, 'PENDING', now(), now()
FROM "Topic" t WHERE t."name" = 'Electrical Apparatus & Devices' AND t."subject" = 'EE'
ON CONFLICT ("kind", "subject", "name") DO NOTHING;
